   absolutely positioned (inset: 0), so height: 100% fills the grid cell. */
.widget {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: var(--g-spacing-4);
  background: var(--g-color-base-float);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-l);
  overflow: hidden;
}

.widget__header {
  display: flex;
  align-items: center;
  gap: var(--g-spacing-2);
  margin-bottom: var(--g-spacing-2);
  flex-shrink: 0;
}

.widget__title {
  flex: 1;
  min-width: 0;
}

/* The flexible body that the chart fills — min-height: 0 so it can shrink. */
.widget__body {
  flex: 1;
  min-height: 0;
}

.widget-stat__delta {
  margin-top: auto;
}

