DashKit.setSettings({
  gridLayout: {
    cols: 36,
    rowHeight: 20,
    margin: [8, 8],
    containerPadding: [0, 0],
  },
});

DashKit.registerPlugins(
  pluginTitle,
  pluginText,
  {
    type: 'stat',
    defaultLayout: {w: 12, h: 5, minW: 6, minH: 4},
    renderer: StatWidget,
  },
  {
    type: 'chart',
    defaultLayout: {w: 18, h: 12, minW: 9, minH: 8},
    renderer: ChartWidget,
  },
);

