              На дашборде пока нет виджетов
            </Text>
            <Text variant="body-2" color="hint">
              Нажмите «Редактировать» и добавьте виджеты с панели внизу
            </Text>
          </div>
        ) : null}
        <DashKitDnDWrapper>
          <DashKit
            editMode={editMode}
            config={config}
            onChange={({config: next}) => setConfig(next)}
            onDrop={onDrop}
          />
          {editMode ? <ActionPanel items={panelItems} /> : null}
        </DashKitDnDWrapper>
      </main>
    </div>
  );
}

